import {JAVA_INTERVIEW_UNITS,JAVA_MOCK_INTERVIEW} from './java-interview-content.mjs';
// Original teaching notes and preparation targets, not employer questions or a hiring score.
export const INTERVIEW_COURSE_REVISION='2026-10-29.1';
const both=['backend','fullstack'];
const section=(title,body,example,pitfall)=>({title,body,example,pitfall});
const practice=(type,id,label)=>({type,id,label,href:`#${type}/${id}`});
const python=(id,label)=>practice('python',id,label);
const sql=(id,label)=>practice('sql',id,label);
export const INTERVIEW_GUIDANCE_SOURCES=[
  {title:'Microsoft technical interviewing',url:'https://careers.microsoft.com/v2/global/en/hiring-tips/technical-interviewing.html'},
  {title:'Amazon software development topics',url:'https://www.amazon.jobs/content/en/how-we-hire/interview-prep/software-development-topics'},
  {title:'React learning documentation',url:'https://react.dev/learn'},
  {title:'MDN web development curriculum',url:'https://developer.mozilla.org/en-US/curriculum/'},
  {title:'W3C accessible forms',url:'https://www.w3.org/WAI/tutorials/forms/'}
];
export const INTERVIEW_UNITS=[
  {id:'problem-solving',title:'Turn a prompt into a testable contract',phase:'Shared foundations',tracks:both,prerequisites:[],
    outcome:'Clarify a requirement, write a small baseline and test a boundary before optimizing.',
    sections:[
      section('Ask questions that change the solution','Start by naming the input and the exact output. Ask about empty input, duplicates, ordering, mutation and failure. Ask only questions that could change the implementation. If a detail is not supplied, state an assumption and proceed with a small example. This shows a collaborator how you reason and prevents a correct solution to the wrong problem.','Prompt: keep unique labels.\nQuestion: preserve the first-seen order or sort them?\nInput: ["b", "a", "b"]\nFirst-seen result: ["b", "a"]\nSorted result: ["a", "b"]','Recognizing a familiar pattern before reading the tie rule can produce an incorrect answer.'),
      section('Build a baseline before the clever version','Give yourself a version you can explain and check. A nested loop can be a useful baseline for pairing entries. State the repeated work it performs, then consider what information could be remembered. Optimization should remove an identified cost while preserving the contract. Do not rewrite a working linear scan into a more complex structure without a reason.','Baseline: compare each earlier entry with the current entry.\nRepeated work: searching earlier values again.\nPossible memory: value -> earliest earlier position.','Naming a hash map is not a correctness argument. Explain exactly what it stores and when it changes.'),
      section('Use a small set of revealing tests','Choose a normal case, the smallest valid case, an exact boundary and a counterexample for your suspected bug. Predict each result before running. If you get stuck, reduce the input until you can simulate one step. In a real interview, explain the partial invariant and the next experiment instead of going silent. After a fix, rerun surrounding cases.','Requirement: values at least 3.\nNormal: [2, 4] -> [4]\nBoundary: [3] -> [3]\nEmpty: [] -> []\nDuplicate: [3, 3] -> [3, 3]','Passing only the displayed sample says little about a strict-versus-inclusive boundary.')],
    practice:[python('threshold-function','Translate an inclusive boundary'),python('stable-unique','Preserve a precise ordering contract')],
    reflect:'Write your clarification, baseline, one invariant, and the smallest test that could disprove your first idea.',
    checks:[['contract','I can restate the exact contract before choosing a pattern.'],['baseline','I can explain a simple correct baseline.'],['test','I can predict an edge case before running code.']],
    followUp:'The interviewer changes the required ordering. Which part of your solution changes, and which invariant stays valid?'},
  {id:'python-fluency',title:'Make Python behavior predictable',phase:'Shared foundations',tracks:both,prerequisites:['problem-solving'],
    outcome:'Write small functions confidently and explain references, mutation, exceptions and return values.',
    sections:[
      section('Trace names and objects separately','A variable name refers to a value or object. Assigning another name to a list does not copy it. A slice creates a new outer list, but nested mutable objects can still be shared. Before changing a collection, read whether the contract requires mutation, a new result, or the exact same object. These are different requirements with different tests.','a = [1, 2]\nb = a\nb.append(3)\n# a is now [1, 2, 3]\nc = a[:]\nc.append(4)\n# a still has three entries','A correct-looking returned list does not prove the input stayed unchanged.'),
      section('Separate a side effect from a returned result','Many mutating methods return None. A function that calls append and returns its result therefore returns None, not the updated list. State whether an operation produces a value, changes existing state, or does both. Use explicit return statements and test identity when the contract cares about it. Keep mutable instance fields inside the instance initializer.','durations = []\nresult = durations.append(5)\n# durations == [5]\n# result is None','A list on a class can become shared state when each object was supposed to own its own history.'),
      section('Keep errors and missing results deliberate','A missing resource can be a normal None result; invalid input may require a specific exception. Do not catch every exception and silently return a plausible value. Validate the promised boundary and let unexpected defects remain visible during development. Python booleans are integer subclasses, so a strict integer API contract may need type(value) is int rather than isinstance(value, int).','Contract: 0 is valid, negative minutes are invalid.\nA zero result must not be treated as missing.\nA malformed value must not silently become zero.','Catching a broad error can hide the exact bug an interviewer is asking you to investigate.')],
    practice:[python('instance-state','Keep two objects independent'),python('append-and-return','Return the required object'),python('list-slices','Copy without mutation'),python('group-totals','Accumulate per-key totals'),python('parse-duration','Handle parse failures intentionally')],
    reflect:'Explain one aliasing bug, one return-value bug, and how your tests distinguish them.',
    checks:[['objects','I can distinguish a shared reference from a copy.'],['returns','I can explain each function’s return value.'],['errors','I can separate an expected missing result from invalid input.']],followUp:'What changes if a list contains other mutable lists? Demonstrate the difference between shallow and deep copying.'},
  {id:'object-design',title:'Give state and responsibilities a clear owner',phase:'Shared foundations',tracks:both,prerequisites:['python-fluency'],
    outcome:'Use functions, objects and dependencies deliberately, with testable responsibilities and explicit invariants.',
    sections:[
      section('An object should protect a meaningful rule','Begin with the state a capability owns and the valid operations on that state. A workout instance may own its own duration list and reject invalid additions. Keep initialization and mutation together so callers cannot accidentally share another instance’s list. A class is not required when a pure function naturally expresses the task; explain the boundary rather than adding objects for ceremony.','Workout invariant: each recorded duration is a nonnegative integer.\nEach instance owns a separate list.\nAn operation either preserves that invariant or reports invalid input.','Inheritance does not repair unclear state ownership or a class that mixes unrelated responsibilities.'),
      section('Prefer a small dependency boundary you can replace','A service that needs stored workouts can depend on a repository interface rather than constructing a database connection inside every operation. Injecting that dependency makes the boundary visible and lets a test substitute a controlled implementation. The test must still include a real database when database behavior is the claim. Composition often keeps such responsibilities clearer than a deep inheritance hierarchy.','Request handler -> service -> repository\nThe service owns the use case.\nThe repository owns the persistence boundary.\nThe trusted actor still comes from the verified session.','A mock repository passing does not establish that the actual SQL, transaction or authorization query works.'),
      section('Object identity is different from equal values','Two nodes can contain the same value while being different objects. A linked structure stores references, not just an ordered list of displayed values. When reversing links, preserve the unprocessed suffix before redirecting a pointer. Tests should inspect identities and termination as well as output values if the contract requires in-place mutation.','a.value == b.value  # May be True\na is b              # Can still be False\nBefore changing current.next, save the following node.\nThe old head must become a tail whose next is None.','Rebuilding fresh nodes may reproduce the values while violating an identity-preserving contract.')],
    practice:[python('instance-state','Protect per-instance state'),python('reverse-chain','Reverse actual object references')],reflect:'State an invariant, one responsibility boundary and one identity-sensitive test. Explain when a simple function is preferable to a class.',checks:[['owner','I can identify who owns mutable state.'],['dependency','I can explain a replaceable dependency boundary.'],['identity','I can distinguish identity from equal values.']],followUp:'How would you test the service in isolation and also prove its real database integration works?'},
  {id:'complexity',title:'Explain cost in terms of the input',phase:'Shared foundations',tracks:both,prerequisites:['python-fluency'],
    outcome:'Justify time and auxiliary space, distinguish average/worst/amortized bounds and identify an expensive repeated operation.',
    sections:[
      section('Define the size variable before naming a bound','Let n be the number of items, u the number of distinct keys, or T a numeric target. Then count the operations whose number grows with that variable. O(1) work is bounded independently of n; a linear scan grows with n; repeatedly halving a candidate region gives logarithmic iterations. Sorting by comparisons is commonly O(n log n), while comparing every pair takes quadratic work.','One pass over n labels: n visits.\nCompare each pair: about n(n-1)/2 comparisons.\nHalve a candidate interval repeatedly: about log2(n) iterations.','A Big-O label without a defined input size can hide the actual source of growth.'),
      section('Look through helpers and count total work','A short method call can scan or copy a whole collection. list membership, slicing and sorting have costs. Nested loops can still be linear when two pointers each move forward at most n times. Conversely, an apparently single loop can be quadratic if it repeatedly searches an ever-growing list. Explain the expensive operation and the invariant that limits how often it occurs.','for label in labels:\n    if label not in result:\n        result.append(label)\n# Searching result can rescan a growing list each time.','Counting indentation levels is not a complexity proof.'),
      section('State the space and guarantee precisely','Separate input storage, required output and auxiliary state. A recursive traversal uses live stack space proportional to depth. A hash-table claim is usually average or expected case; append has amortized cost because occasional resizes copy existing entries. A target-indexed dynamic-programming table can depend on the numeric target rather than the number of input characters. Measurements complement these arguments but do not replace them.','Tree traversal: O(n) visits, O(h) live recursive calls.\nFrequency scan: expected O(n) time, O(u) count state.\nTarget table: O(T) states, not O(number of digits in T).','Saying O(1) space while keeping a growing visited set, output copy or recursion stack omits real storage.')],
    practice:[],reflect:'Choose a loop, a search and a recursive function. Define the size variables, count repeated work and state auxiliary versus output space.',checks:[['size','I define what n, u or T means.'],['work','I can justify the repeated work rather than count loop nesting.'],['space','I can distinguish expected, amortized and worst-case claims.']],followUp:'A linear algorithm copies a large string at every iteration. What additional input-size cost could change your bound?'},
  {id:'data-structures',title:'Choose the structure that fits the operation',phase:'Coding patterns',tracks:both,prerequisites:['object-design','complexity'],
    outcome:'Compare arrays, linked nodes, hash tables, stacks, queues and heaps by the operation the problem needs.',
    sections:[
      section('Indexed access and linked traversal have different costs','An array/list offers direct access by index, while inserting near its beginning shifts later elements. A linked chain follows references to reach a position. Insertion next to an already-known node can change a few links, but finding that node may still require a scan. Include locality, extra node storage and the operations the application actually performs before claiming one structure is better.','Array question: what is the item at index i?\nLinked question: which node does this reference point to next?\nChanging known links is different from searching for a node.','Calling every linked-list insertion constant time ignores the cost of locating the insertion point.'),
      section('Match work-list order to the invariant','A stack processes the newest pending item first. A queue processes the oldest first. The collection itself does not prove correctness; its ordering must match the rule. A stack is useful for nested brackets. A FIFO deque supports equal-cost breadth-first search. Repeatedly removing index 0 from a Python list shifts elements, so use a suitable queue implementation when that operation dominates.','Nested obligation -> last opened, first closed.\nUnweighted shortest route -> explore distance layers in FIFO order.','Changing a queue to a stack can preserve reachability while breaking a shortest-route result.'),
      section('A heap exposes a priority boundary, not a sorted sequence','A heap maintains a partial ordering sufficient to retrieve its root priority. It does not keep all entries in display order. For k smallest values, retain only k candidates and expose the largest retained value so a smaller incoming value can replace it. Keep duplicates when they are separate events, and sort the selected output if the contract requests sorted results.','Selected smallest k values: keep a bounded max-priority boundary.\nA Python min-heap can model that boundary using negated integers.\nFinal sorted output still needs its own ordering step.','Using a set as the selected structure loses duplicate occurrences and can change the answer.')],
    practice:[python('reverse-chain','Work with actual links'),python('smallest-events','Maintain a bounded priority set')],reflect:'For a scan, indexed lookup, nested parser, shortest path and small-k selection, state the required operation and the structure it suggests.',checks:[['operations','I choose structures from required operations.'],['ordering','I can explain what a stack, queue or heap guarantees.'],['tradeoff','I can compare time, memory and output-order costs.']],followUp:'If k is almost n, would a heap still be your clearest solution? Compare the full-sort alternative.'},
  {id:'hashing',title:'Remember only the information you need',phase:'Coding patterns',tracks:both,prerequisites:['data-structures'],
    outcome:'Choose between a set, a frequency map and an index map, and justify the choice.',
    sections:[
      section('Presence, frequency and position answer different questions','A set answers whether something has appeared. A frequency map answers how often it appeared. An index map answers where an earlier occurrence is located. Decide which question the next step needs before choosing the stored value. A collection of labels and a count of labels are not interchangeable. Preserve the specified case and normalization rules.','Presence: {"open", "tap"}\nFrequency: {"open": 1, "tap": 3}\nFirst position: {"open": 0, "tap": 1}','Overwriting a count with 1 loses repeated events while still looking reasonable on unique input.'),
      section('State an invariant for a one-pass lookup','For a pair search, an index map can describe only positions strictly before the current one. Query before insertion to preserve that rule. Retain the earliest index when ties matter. Walk through a one-item input whose value is half the target: a solution that inserts first may incorrectly pair the entry with itself.','Target 10, values [5]: no pair.\nTarget 10, values [5, 5]: indices [0, 1].\nSame values, different number of entries.','A mathematically matching value is not enough if the two indices must be distinct.'),
      section('Explain average-case cost and ordering','A hash-based scan often has expected linear time, with space for distinct keys. Be clear about assumptions and include string hashing or comparison cost when relevant. A set does not express a required output ordering. If ranking is requested, count first and apply a complete ordering rule, including ties. Discuss a heap only when small k makes it useful.','Ranking key: (-frequency, label)\nThis means high frequency first, then ascending label.\nInsertion order is not a declared tie rule.','Saying every dictionary operation is guaranteed constant time overstates the complexity claim.')],
    practice:[python('label-counts','Build a frequency map'),python('stable-unique','Combine a set with ordered output'),python('budget-pair','Find a complement without reusing an index'),python('top-labels','Rank with deterministic ties')],
    reflect:'For each drill, name the dictionary/set invariant and why the stored information is sufficient.',checks:[['choice','I can choose presence, count or position deliberately.'],['invariant','I can explain why an entry cannot match itself.'],['cost','I can justify time, space and tie ordering.']],followUp:'What if labels arrive as a stream too large to retain? Which answers require storing all distinct labels, and what approximations would change the contract?'},
  {id:'windows',title:'Move boundaries instead of rescanning',phase:'Coding patterns',tracks:both,prerequisites:['hashing'],
    outcome:'Use two pointers and a sliding window with a maintained invariant and a termination argument.',
    sections:[
      section('Two pointers exploit a known order','When two lists are sorted, the smaller of their current unconsumed items is the next output value. Consume one side at a time and state what the output prefix already guarantees. Both pointers only move forward. The loop ending means one list is exhausted, not that the other list should be ignored.','Left: [1, 4]\nRight: [2, 3, 8]\nConsume: 1, 2, 3, 4\nRemaining tail: 8','A tail case may be absent from the sample but is still part of every merge contract.'),
      section('A window is a contiguous region with a rule','Define the active region and the property it maintains. For unique labels, the window must contain no repeated label. Adding one label may require moving the left boundary past its earlier occurrence. An older occurrence outside the window should not move the boundary backward. Store the latest position and keep the boundary monotonic.','Labels: ["a", "b", "b", "a"]\nAfter the second b, the window starts at index 2.\nThe old a at index 0 cannot move it back to index 1.','Counting distinct values in the entire list ignores the requirement that the segment be contiguous.'),
      section('Count pointer movement, not just loop syntax','Nested loops do not automatically imply quadratic work. If each pointer advances at most n times across the whole algorithm, total movement is linear. Conversely, repeatedly slicing or rescanning a large window can add hidden work. Explain what changes when the rule no longer allows monotonic boundaries, such as arbitrary negative sums in some window problems.','Proof shape: right advances at most n times.\nleft also advances at most n times.\nThere are at most 2n boundary advances.','Do not transfer a sliding-window rule to a new problem without proving the property that makes shrinking safe.')],
    practice:[python('merge-checkpoints','Merge ordered inputs'),python('unique-window','Maintain a unique contiguous segment')],reflect:'Draw the pointer positions on a four-item counterexample. Explain why neither boundary moves backward.',checks:[['order','I can explain what sorted input permits.'],['window','I can state the window invariant.'],['movement','I can bound total pointer movement.']],followUp:'If you also need the earliest longest segment, what additional values and tie rule must you keep?'},
  {id:'search-stack',title:'Make boundaries and nested state explicit',phase:'Coding patterns',tracks:both,prerequisites:['windows'],
    outcome:'Use a stack for nested obligations and binary search for a monotone boundary.',
    sections:[
      section('A stack remembers the most recent unfinished obligation','Nested structures finish in reverse opening order. A closing bracket must match the newest unclosed opening bracket. Counting opens and closes loses order and accepts crossed pairs. Check the empty stack before popping, and reject any leftover openings after the scan. The same last-in-first-out idea appears in undo operations and iterative traversals.','([)] has equal counts but invalid nesting.\nFor ([, the next valid closer is ], not ).','A test of balanced totals is weaker than a test of proper nesting.'),
      section('Binary search finds a boundary, not just a value','Write down what the search interval means. In a half-open [lo, hi) search for the first value at least target, everything before lo is known to be too small. Equality stays on the qualifying side. An empty input and an insertion position after the final element should fall out of the same invariant rather than special-case guesses.','Values: [1, 3, 3, 7], target 3\nFirst qualifying index: 1\nValues: [], target 3\nFirst qualifying index: 0','Returning any matching duplicate does not satisfy a first-position contract.'),
      section('Prove termination alongside correctness','Each iteration must discard a nonempty part of the candidate interval. If mid is too small, advance lo to mid + 1. Otherwise set hi to mid. At lo == hi, one boundary remains. Before changing < to <=, walk through a one-element case to check that the interval shrinks and the final index is still legal.','At every loop step: hi - lo strictly decreases.\nAt termination: the candidate boundary is lo.','An algorithm that is correct when it terminates still fails if a boundary update can repeat the same state forever.')],
    practice:[python('balanced-route','Validate nested markers'),python('first-at-least','Find a lower boundary')],reflect:'Explain a failing nested-marker case and the meaning of lo and hi without reading the code.',checks:[['stack','I can explain why equal counts are insufficient.'],['boundary','I can state the half-open search invariant.'],['termination','I can prove every iteration makes progress.']],followUp:'Change the search to the first value strictly greater than target. Which comparison changes and why?'},
  {id:'graphs-intervals',title:'Order intervals and explore reachable states',phase:'Coding patterns',tracks:both,prerequisites:['search-stack'],
    outcome:'Clarify interval semantics and choose traversal based on the question rather than habit.',
    sections:[
      section('Decide whether touching intervals overlap','Write the interval notation before merging. With half-open intervals [start, end), [1, 3) and [3, 5) do not overlap. Sorting by start allows a scan that compares the next interval with the last merged one. Use the maximum end to keep a contained interval from shortening the combined result. Copy nested output pairs when mutation is forbidden.','[1, 3) and [3, 5): two separate bookings.\n[1, 4) and [3, 5): merge into [1, 5).','A comparison copied from an inclusive-interval problem can silently change the required behavior.'),
      section('Use breadth-first search for equal-cost shortest routes','A FIFO queue explores all routes of length d before moving to length d + 1. The first visit to a goal therefore establishes minimum hops when all links cost the same. Mark states as seen when enqueuing them to avoid repeated work from cycles and duplicate edges. A stack explores depth first and does not give the same shortest-route guarantee.','A short branch reaches the goal in 2 links.\nA deep branch reaches it in 3.\nDepth-first exploration can encounter the deep answer first.','The fewest links and the lowest weighted cost are different questions.'),
      section('Specify the graph boundary','Clarify directed versus undirected edges, missing endpoints, self-routes and unreachable goals. Name V and E in the complexity statement. An adjacency-list traversal visits reachable vertices and adjacency entries, with a visited set bounded by vertices. Do not promise graph performance based only on the number of edges shown in a tiny drawing.','Existing start == goal: 0 hops.\nMissing start or goal: None.\nNo path in a disconnected graph: None.','Assuming all nodes are connected hides precisely the failure an unfamiliar fixture may test.')],
    practice:[python('merge-bookings','Merge half-open bookings'),python('shortest-link-hops','Find a minimum-hop directed route')],reflect:'Explain one endpoint assumption, one cycle test, and why your traversal order matches the objective.',checks:[['interval','I can explain endpoint inclusion.'],['traversal','I can distinguish BFS from DFS guarantees.'],['graph','I can test cycles, missing nodes and unreachable nodes.']],followUp:'What changes when a link can cost 2 or 10 instead of 1? Explain why FIFO alone no longer proves a minimum-cost answer.'},
  {id:'recursion-dp',title:'Define smaller subproblems precisely',phase:'Coding patterns',tracks:both,prerequisites:['graphs-intervals'],
    outcome:'Write a base case and recurrence, then justify whether subproblem results need to be remembered.',
    sections:[
      section('Make recursive calls answer a smaller version of the same question','For a tree depth, each child subtree is a smaller tree with exactly the same depth definition. The empty tree supplies a base case. A nonempty tree adds one root to the deeper child result. Explain both returned values and the maximum number of simultaneously live calls. Python recursion has practical limits, so mention an explicit-stack alternative for unbounded nesting.','depth(None) = 0\ndepth(node) = 1 + max(depth(left), depth(right))','Counting only one branch works on a skewed sample and fails as soon as the deeper branch switches sides.'),
      section('Dynamic programming stores answers to repeated subproblems','Start with a state whose meaning is exact. For a target made from reusable cell sizes, best[t] means the minimum count to reach exactly t. The final cell leaves a smaller exact target. Enumerating possible last cells yields a recurrence. Compute smaller targets first and distinguish an unreachable state from a valid zero-cell result.','best[0] = 0\nbest[t] = minimum of best[t - size] + 1\nfor usable final sizes whose remainder is reachable','A greedy choice of the largest size has no general optimality guarantee.'),
      section('Challenge the tempting shortcut','Test a greedy strategy with sizes [1, 3, 4] and target 6: 4 + 1 + 1 uses three cells, while 3 + 3 uses two. State the complexity in terms of the numeric target and size count. A table indexed up to a large target can be too expensive even when the input text is short. The state definition, recurrence, evaluation order and result extraction are all part of the explanation.','Counterexample: sizes [1, 3, 4], target 6.\nAlso test target 0 and a positive unreachable target.','Calling every table-based algorithm efficient ignores the size of the state space.')],
    practice:[python('tree-depth','Measure a tree’s depth'),python('fewest-cells','Optimize reusable choices with a table')],reflect:'Write the state definition, base case, recurrence, order of evaluation, time bound and memory bound.',checks:[['base','I can justify the base case.'],['recurrence','I can explain why every optimal answer is represented.'],['bounds','I can identify limits on recursion depth or table size.']],followUp:'How would you return an actual optimal choice of cells instead of only the minimum number?'},
  {id:'sql-foundations',title:'Build SQL from rows, keys and relationships',phase:'Backend and full-stack data',tracks:both,prerequisites:['problem-solving'],
    outcome:'Create a small relational model and predict filters, joins and grouped results before running them.',
    sections:[
      section('Name one row and the keys that make it valid','A table should represent a clear kind of record. A primary key identifies a row; a foreign key constrains a relationship to another table. NOT NULL, UNIQUE and CHECK rules express different requirements. Creating a join does not create a constraint. Prove important rules by attempting an invalid write, not by merely drawing a line in a diagram.','customers: one row per customer.\norders: one row per order, pointing to a customer.\nOne customer may have zero, one or many orders.','A query can hide an orphan row while the invalid data still exists in the database.'),
      section('Predict filtering and joining as row operations','SELECT chooses output expressions, FROM supplies rows, WHERE keeps qualifying rows and ORDER BY supplies a requested order. INNER JOIN keeps matching pairs; LEFT JOIN also keeps an unmatched left row with NULL child fields. Think through a parent with zero children and another with two before counting results. SQL NULL requires IS NULL or IS NOT NULL for explicit null tests.','One customer with 2 orders creates 2 matching join rows.\nA second customer with no orders disappears from an INNER JOIN.\nA LEFT JOIN can retain the second customer.','Rows have no guaranteed display order without an ORDER BY that fully resolves relevant ties.'),
      section('Group at the requested result grain','GROUP BY combines rows into groups. SUM combines measures, COUNT counts qualifying values and HAVING filters the resulting groups. WHERE filters before grouping. COUNT(child_id) ignores NULL child IDs, whereas COUNT(*) counts joined rows, including a null-extended parent row. Choose whether the question wants orders, customers or distinct products before adding DISTINCT.','WHERE: keep paid input orders.\nGROUP BY: one result group per customer.\nHAVING: keep groups whose total exceeds a threshold.','A valid-looking aggregate can count the wrong thing if the result grain was never defined.')],
    practice:[sql('schema-join','Create and enforce a relationship'),sql('paid-orders','Filter and order real rows'),sql('inner-join','Predict matching pairs'),sql('left-join-count','Retain a zero-child parent'),sql('group-having','Filter groups deliberately'),sql('not-exists','Find an absent relationship')],
    reflect:'Draw two parent rows and three child rows. Predict the inner join, left join and grouped count before executing each query.',checks:[['model','I can state one row’s meaning and its constraints.'],['join','I can predict matching and unmatched join rows.'],['group','I can distinguish row filtering from group filtering.']],followUp:'Move a child-table condition from ON into WHERE. Which parents disappear, and why?'},
  {id:'sql-reasoning',title:'Explain the meaning of every result row',phase:'Backend and full-stack data',tracks:both,prerequisites:['sql-foundations','hashing'],
    outcome:'Handle SQL cardinality, missing rows, ties, date windows and window frames without sample-specific fixes.',
    sections:[
      section('Choose the result grain before the join','State what one result row represents: a customer, an order, or a summary period. Two independent child collections can multiply each other when joined raw. Aggregate each child to the parent grain before combining measures. DISTINCT is not a universal repair: equal payment amounts can represent different payments and must still both count.','One customer, 2 tasks, 2 payments:\nraw join -> 4 rows.\nPre-aggregate tasks and payments -> one summary from each.','A count repaired with DISTINCT can still leave an inflated sum.'),
      section('Treat absence and tie policies as requirements','A left join can preserve a parent with no child, but a WHERE condition on that child may remove it again. COUNT(child_id) and COUNT(*) differ on the null-extended row. For rankings, distinguish a fixed number of people from a number of distinct score levels. For a single missing aggregate result, decide whether the contract asks for no row or one NULL row.','ROW_NUMBER: one position per person.\nRANK: equal scores tie, later rank may skip.\nDENSE_RANK: one rank per distinct score level.','A second row after sorting is not necessarily the second distinct value.'),
      section('Make time and order deterministic','An ISO date is not necessarily a unique ordering key. Add a stable tie breaker and specify a ROWS frame for row-by-row cumulative totals. Define date windows as inclusive or half-open before writing BETWEEN. SQLite calendar-date practice is different from a production API’s timezone and elapsed-duration policy. Explain what an index can support and verify its actual plan.','First 7 calendar days:\njoined_at <= active_at < joined_at + 7 days\nThis includes day 0 and excludes day 7.','A query that looks correct with unique timestamps can fail as soon as two rows share a date.')],
    practice:[sql('latest-order','Choose a deterministic latest row'),sql('paid-summary','Keep zero-match customers'),sql('avoid-fanout','Aggregate independent child tables'),sql('rank-ties','Preserve score ties'),sql('running-balance','Define a deterministic frame'),sql('second-distinct-score','Return the correct missing aggregate'),sql('first-week-activity','Apply an exact date boundary')],reflect:'Pick one incorrect query. Predict its wrong rows before running it, then explain the relational assumption that caused them.',checks:[['grain','I can predict join cardinality before executing.'],['absence','I can distinguish NULL, no row, and zero.'],['ties','I can justify the ordering, rank or window boundary.']],followUp:'What index would help the member-and-date query, and what write or storage cost would that introduce?'},
  {id:'testing-debugging',title:'Investigate a failure and protect the repair',phase:'Engineering practice',tracks:both,prerequisites:['sql-reasoning','python-fluency'],
    outcome:'Build a minimal reproducer, test a hypothesis and explain which testing layer supports each claim.',
    sections:[
      section('Separate the symptom, hypothesis and observed cause','Record the exact input and what should have happened before changing code. Reduce a large failing input while preserving the failure. A hypothesis predicts an observation; inspect variables or a real source-linked trace to challenge it. Keep the failing test before the repair so another person can reproduce the bug and understand why the change is necessary.','Symptom: a duplicate request creates two rows.\nHypothesis: uniqueness is checked only in application memory.\nExperiment: send two concurrent requests and inspect committed rows.','Restating the error message is not a root-cause explanation.'),
      section('Choose unit, integration and browser checks for different claims','A unit test can isolate a pure function or state transition. An integration test can observe SQL constraints, persistence and transaction effects. A browser test can check labels, focus, interaction, loading and rendered error states. Controlled mocks help exercise failures, but a mock cannot establish behavior of the real system it replaces. Prefer assertions about observable results over copying implementation details.','Pure validation -> small function test.\nCross-owner lookup -> real API/database integration.\nStale result on screen -> controlled network plus real browser assertion.','A mocked successful request does not prove that the production endpoint exists or returns the expected data.'),
      section('Test the counterexample and nearby behavior','After a repair, rerun the case that failed and the cases it might affect: empty input, exact boundary, duplicates, error and cancellation paths. For async UI, control response order. For databases, inspect actual state before and after failure. Add bounded diagnostic context without logging passwords, OTPs or private payloads. State what your checks leave untested.','Regression record: test fails before repair, passes after repair.\nNeighboring checks: the previous valid behavior remains intact.\nLimit: this local run does not establish every browser or production condition.','Broad new tests that only repeat the implementation can all pass while the original user-facing defect remains.')],
    practice:[python('parse-duration','Investigate a parsing boundary'),sql('safe-update','Verify changed and unchanged rows')],reflect:'Save a symptom, minimal input, hypothesis, observed cause, regression test and remaining limitation from one deliberate bug.',checks:[['reproduce','Another person can reproduce my failure.'],['layer','I can choose the testing layer for the claim.'],['repair','I can show the regression before and after the repair.']],followUp:'A unit test passes but production still fails. Which environment, integration and input differences would you inspect first?'},
  {id:'http-data',title:'Connect HTTP contracts with consistent data',phase:'Backend systems',tracks:both,prerequisites:['sql-reasoning'],
    outcome:'Explain status and retry semantics, a transaction boundary, and a compatible API/data change.',
    sections:[
      section('An HTTP contract includes unsuccessful outcomes','Describe the method, route, input fields, success status/body and expected failures. GET should retrieve without requesting a state-changing operation. A validation rejection, missing resource, forbidden ownership and revision conflict need deliberate behavior. A client timeout is an ambiguous outcome, not evidence that the server rolled back. CORS controls browser cross-origin access; it is not authorization.','POST /workouts: validated create request.\nGET /workouts/9: owner-scoped read.\nConflict: reject a stale revision and ask the client to review.\nEvery failure needs a defined client recovery path.','A single generic success response can force the frontend to guess whether the operation actually happened.'),
      section('A transaction is an atomic boundary, not every consistency guarantee','Group dependent database changes so they commit or roll back together. Concurrent requests can still observe or compete over data according to the isolation level and engine. State the read-modify-write risk, then use a suitable atomic update, uniqueness rule, lock or revision predicate. A browser SQLite exercise does not reproduce every MySQL/Postgres isolation behavior; investigate concurrency in real separate connections.','Old revision 4 -> update WHERE owner_id=? AND revision=4.\nOne writer succeeds and advances the revision.\nA second stale writer affects no row and must not silently overwrite it.','Application validation followed by an unprotected write can race with another request.'),
      section('Prefer compatible evolution and verify an access path','An API or schema change may need old and new clients to coexist. Add compatible fields, backfill safely and define how older clients behave before removing an old representation. Indexes support particular predicates and orders, while adding storage and write cost. Inspect an actual execution plan and realistic data distribution. A rollback plan must account for data changes, not just code version.','Potential index: (owner_id, created_at, id)\nUseful query: one owner, then a deterministic time-and-ID cursor.\nThe exact plan must be observed, not inferred from the index name.','A faster sample query does not prove an index helps every workload or that a migration is reversible.')],
    practice:[sql('rollback','Observe an atomic rollback'),sql('index-plan','Inspect the engine’s plan'),sql('keyset-page','Keep a stable cursor order')],reflect:'Write a small API contract with errors, a transaction/revision rule and a compatible change plan.',checks:[['http','I can describe failure responses and retry implications.'],['transaction','I can explain atomicity versus concurrent consistency.'],['evolution','I can justify a query access path and a compatible change.']],followUp:'A client retries after losing the create response. What durable information allows a safe replay across a server restart?'},
  {id:'backend-design',title:'Follow a request through ownership and failure',phase:'Backend systems',tracks:both,prerequisites:['http-data','testing-debugging'],
    outcome:'Explain an API contract, trusted ownership, transaction boundary and bounded failure policy.',
    sections:[
      section('Separate validation from authorization','Validation asks whether data has the right shape and range. Authorization asks whether this actor may perform this action on this resource. The server obtains the actor from its verified session, not from a browser-supplied owner ID. A resource query should include ownership in the trusted predicate. Client-side validation improves feedback but cannot establish server trust.','GET /workouts/9\nTrusted actor: session user 1\nLookup: id = 9 AND user_id = 1\nThe request does not choose its own trusted actor.','A valid resource ID can still belong to another user.'),
      section('Draw the transaction and retry boundary','A client timeout does not prove a server write failed. Design duplicate delivery around a stable owner-scoped key and durable uniqueness. Store the effect and replay result atomically where the contract needs it. Bound retry attempts and the total deadline. If database state and an event must agree, an outbox can remove a dual-write gap, while consumers still need duplicate handling.','Write commits -> response is lost -> client retries.\nThe retry must not create another business effect.\nSame key with a changed payload needs an explicit policy.','An in-memory seen flag does not survive restart or coordinate multiple servers.'),
      section('Start simple and explain the failure that earns complexity','A small product can begin as a modular monolith. Add a cache, queue or service boundary for a specific measured or reasoned need. A read-cache hit cannot complete a write. Queue acceptance is not completion. Explain source of truth, consistency needs, capacity assumptions and recovery. The design lab calculates an educational flow model; it does not certify a production architecture.','For each component, ask:\nWhat enters it? What leaves it? Who owns the state?\nWhat happens if it is slow, unavailable, or duplicated?','Naming more infrastructure is not the same as showing a correct request path.')],
    practice:[python('validate-workout-payload','Validate the API boundary'),python('owner-scoped-read','Scope a read to its owner'),sql('retry-safe-insert','Keep retries from overwriting results'),sql('safe-update','Constrain a data change'),sql('rollback','Observe a real rollback'),sql('index-plan','Inspect an actual query plan'),sql('keyset-page','Use a stable pagination cursor')],
    links:[{href:'#architecture',label:'Practice six design discussions'},{href:'#design',label:'Investigate the system design model'}],reflect:'Trace one create request and one failed retry. State the transaction, owner predicate, deadline and response policy.',checks:[['ownership','I can distinguish validation from authorization.'],['retry','I can explain an ambiguous timeout and safe replay.'],['failure','I can describe recovery and the model’s limits.']],followUp:'Two clients update the same record from the same old revision. How does the API prevent a silent lost update?'},
  {id:'web-basics',title:'Connect HTML, CSS and the browser request',phase:'Frontend foundations',tracks:['fullstack'],prerequisites:['problem-solving'],
    outcome:'Explain a semantic page, the CSS box model and the path from a browser interaction to an HTTP response.',
    sections:[
      section('HTML describes structure and controls','Use headings for hierarchy, a main region for the page task, labels for form fields and real links or buttons for interactions. Start with a working document before adding style. The browser builds a DOM and exposes semantics to assistive technology; visual position alone does not supply a meaningful reading or focus order.','<main>\n  <h1>Workout journal</h1>\n  <form>\n    <label for="title">Title</label>\n    <input id="title" name="title">\n    <button type="submit">Save workout</button>\n  </form>\n</main>','A heading-sized div looks like a heading but does not provide the same document semantics.'),
      section('CSS controls layout under real constraints','An element’s box includes content, padding and border; margin separates boxes. box-sizing: border-box makes a declared width include padding and border. Flexbox arranges along an axis; grid defines rows and columns. Let children shrink with min-width: 0 where needed and wrap long text. Media queries adapt a task to the available space; zoom and a phone keyboard can change the usable viewport.','A form needs a readable label, a field and a reachable button.\nCheck that long errors wrap instead of widening the whole page.\nInspect both a narrow screen and 200% text zoom.','A fixed pixel width can fit a screenshot while overflowing a real phone or zoomed view.'),
      section('Follow the request and the trust boundary','A form handler reads user input, updates UI state and may send an HTTP request. The server checks the contract and trusted session, performs work and returns a status and body. The browser interprets both and updates the screen. Cookies, CORS, caching and authorization answer different questions. Never keep provider API credentials or passwords in browser progress to make an integration appear to work.','User action -> browser state -> HTTP request\n-> server validation + authorization -> data operation\n-> HTTP status/body -> browser result state','A server response with status 200 does not prove the browser rendered the right result, and a browser check does not secure the API.')],
    practice:[],arcade:['form-minutes','http-outcomes'],reflect:'Trace a labeled form submission in your own project. Explain the DOM structure, responsive layout, request, trusted owner and returned UI state.',checks:[['html','I can choose semantic page and form elements.'],['layout','I can explain box sizing and a layout that shrinks.'],['request','I can follow a request across the browser/server boundary.']],followUp:'What should happen when JavaScript fails to load, a response is slow, or a user cannot use a mouse?'},
  {id:'javascript',title:'Read JavaScript values and updates accurately',phase:'Frontend foundations',tracks:['fullstack'],prerequisites:['web-basics'],
    outcome:'Explain references, immutable updates, missing values, closures and asynchronous sequencing.',
    sections:[
      section('Know which object changes','Arrays and objects are reference values. A new outer array can preserve an old array while still sharing nested object references. push returns a number and mutates its receiver. Read the exact requirement before choosing map, filter, spread or an in-place method. A change that is appropriate inside one owned object can be a bug when that object is shared state.','const original = ["a"];\nconst next = [...original, "b"];\n// original.length is 1, next.length is 2','An outer spread is not a deep copy of every nested object.'),
      section('Distinguish missing from falsy','Zero, false and an empty string can all be meaningful values. || falls back for every falsy value, while ?? falls back for null and undefined. Use strict equality when type coercion is not part of the contract. State the input types rather than relying on accidental conversions from form text or JSON.','0 || "Loading"   // "Loading"\n0 ?? "Loading"   // 0\nnull ?? "Loading" // "Loading"','A real empty count should not appear to be an unfinished network request.'),
      section('A callback closes over a particular environment','A closure can retain a variable binding or a render’s captured value. Async code resumes after current synchronous work has completed, and responses can arrive out of order. Trace when a value is read, when work is scheduled and when state is committed. await makes sequencing inside one async function clearer, but it does not serialize unrelated requests or eliminate races.','Request A starts.\nRequest B starts later and becomes current.\nA finishes after B. A is still stale.','Reading the visually latest callback as the logically latest request confuses arrival with intent.')],
    practice:[],arcade:['immutable-labels','nullish-count'],reflect:'Explain a mutation example, a valid zero and a stale closure in your own words. Include the input/output contract for each.',checks:[['reference','I can explain which object changes.'],['missing','I can preserve a meaningful falsy value.'],['closure','I can trace when a callback reads its values.']],followUp:'What changes when the array contains objects and one nested field needs to be updated without mutating prior state?'},
  {id:'async-ui',title:'Make loading, errors and races visible',phase:'Frontend behavior',tracks:['fullstack'],prerequisites:['javascript'],
    outcome:'Design an async screen whose state stays correct under empty results, HTTP errors, cancellation and out-of-order responses.',
    sections:[
      section('Write the state transitions before the request','A data screen needs distinct idle, loading, success, empty and error behavior. Decide what remains visible while refreshing. fetch resolving does not establish HTTP success: check response.ok, then parse the expected body and validate its shape. A rejected network promise, a 401 response and invalid JSON have different causes and may need different recovery.','idle -> loading -> ready with items\nloading -> ready with no items\nloading -> HTTP error or network error','Showing an old success result after the input changed can be as misleading as displaying a stale pass badge.'),
      section('Commit only the current request’s result','Assign a request identity when the user changes the query. A response may update state only if its identity still matches the current request. Cancel obsolete work where supported, and clean up when a component leaves. Identity checks and cancellation address related but different concerns. Avoid a loading flag that an old request can clear while a newer request is still pending.','Current request: 8\nResponse 7 finishes: ignore it.\nResponse 8 finishes: commit its result.','An old request’s finally callback can incorrectly hide the spinner for a newer request.'),
      section('Test the failure path on purpose','Use controlled delays and synthetic responses in your own project. Start one request, start another, finish the second first and then release the first. Confirm the latest result remains visible. Also test empty success, server failure, session expiry and leaving the screen while work is pending. A retry button should describe and repeat the intended operation rather than reset unrelated state.','Race fixture: second request returns ["new"], then first returns ["old"].\nExpected final items: ["new"].\nA valid [] result gets an empty-state message.','Testing only the fast successful request does not exercise the state machine you just designed.')],
    practice:[],arcade:['latest-request','http-outcomes'],reflect:'Describe your state transitions and the exact assertion that catches an out-of-order response bug.',checks:[['http','I distinguish HTTP failure, network failure and empty success.'],['race','I can prevent stale responses from overwriting current state.'],['cleanup','I can explain cleanup and retry behavior.']],followUp:'How would optimistic updates change your rollback and conflict policy when the server rejects a write?'},
  {id:'accessible-ui',title:'Build an interface someone can actually use',phase:'Frontend behavior',tracks:['fullstack'],prerequisites:['javascript'],
    outcome:'Explain semantic controls, form feedback, responsive layout and keyboard/reduced-motion behavior.',
    sections:[
      section('Start with the semantic control','Use a button for an action and a link for navigation. Associate a visible label with its field; a placeholder is not a durable label. Group related choices with a fieldset and legend. A custom clickable div does not inherit button focus, keyboard activation or disabled behavior. When a task changes state, expose that state in text and appropriate control semantics.','<label for="minutes">Minutes</label>\n<input id="minutes" name="minutes" inputmode="numeric">\n<button type="submit">Save workout</button>','Adding a click handler and a pointer cursor does not make a complete keyboard-accessible control.'),
      section('Validate the whole value and explain recovery','A text input must be checked against its entire grammar and range. parseInt can accept the prefix of invalid text such as 12min. Keep a useful error near the field, connect it programmatically when needed and preserve the user’s valid work. Validate again at the API. Never treat client-side validation as proof of authorization or assume screen-reader output matches appearance.','Field contract: digits only, 0 through 1440.\n"0" is valid; "12min", "2.5" and an empty string are invalid.','A red border alone does not tell someone what failed or how to fix it.'),
      section('Responsive layout is a task, not a scaled screenshot','Inspect narrow and desktop widths with real text and error states. Allow zoom, give controls usable touch areas and keep fixed navigation from covering content or focus. Use grid/flex rules that can shrink their children and allow long text to wrap. Respect reduced motion without removing the information. For performance, measure a concrete bottleneck before adding memoization or virtualization.','Phone checks: labeled inputs, visible errors, reachable primary action.\nKeyboard checks: logical focus order and visible focus.\nMotion checks: the same result without decorative movement.','A layout that fits only the empty form has not been checked with its actual error and loading content.')],
    practice:[],arcade:['form-minutes'],reflect:'Record an actual keyboard test, one narrow-screen measurement, and one error-state test from your own page. These observations are self-reported.',checks:[['semantics','I can justify button, link, label and group semantics.'],['feedback','I can connect an error to the field and recovery action.'],['responsive','I checked touch, zoom, focus and reduced motion.']],followUp:'A fixed bottom bar hides the focused input when the phone keyboard opens. What measurements and layout changes would you investigate?'},
  {id:'react-state',title:'Explain React state, effects and component boundaries',phase:'Frontend framework reasoning',tracks:['fullstack'],prerequisites:['async-ui','accessible-ui'],
    outcome:'Distinguish state snapshots, derived values, effects, identity and real browser evidence.',
    sections:[
      section('A render is a snapshot','Event handlers see values from the render that created them. Repeating setCount(count + 1) uses the same captured value. When the next value depends on preceding queued state, use a functional updater. Do not mutate existing state and expect a component to infer every change. Derive values during rendering when they can be calculated from existing state, rather than storing redundant copies that can disagree.','Captured replacement twice from count 0 requests 1 twice.\nTwo queued updates previous => previous + 1 produce 2.','A pure updater example explains one rule. It does not execute React or test a component.'),
      section('Use effects for synchronization, not every calculation','An effect synchronizes the component with an external system, such as a subscription or request. State its dependencies and its cleanup. Do not silence dependency warnings by deleting meaningful dependencies. Consider whether the work belongs in an event handler or can be derived without an effect. Test unmount and changed-input behavior because cleanup must remain correct across repeated setup cycles.','Question before an effect: what external system is being synchronized?\nIf the answer is only another computed display value, derive it instead.','An effect that starts requests on every render can create loops or stale response races.'),
      section('Identity affects what state is preserved','A list key should identify the logical item across insertions and reordering. Index keys can attach an input’s local state to the wrong item when order changes. State ownership should follow the component boundary that needs to coordinate it. A small pure helper can be tested with Node, while actual rendering, focus, cleanup and interaction require a real component/browser test.','List changes from [A, B] to [B, A].\nA stable item key follows the item.\nA position key follows the slot.','Adding memoization cannot repair incorrect state ownership, mutation or unstable identity.')],
    practice:[],arcade:['state-updaters'],reflect:'Explain one state snapshot, one effect cleanup and one stable-key case. Link a component test or browser observation from your own project.',checks:[['snapshot','I can explain captured values and functional updaters.'],['effect','I can justify an effect and its cleanup/dependencies.'],['identity','I can explain key stability and state ownership.']],followUp:'A slow component rerenders frequently. How would you measure the cause before choosing memoization, state relocation or a smaller component boundary?'},
  {id:'delivery',title:'Defend a working feature and your decisions',phase:'Interview rehearsal',tracks:both,prerequisites:['backend-design'],
    outcome:'Give an evidence-led project walkthrough, respond to a changed requirement and describe your own work honestly.',
    sections:[
      section('Tell one end-to-end feature story','Choose a small feature you can actually demonstrate. Follow a user action through UI state, HTTP validation, trusted ownership, persistence and the returned result. Show one rejected request and one recovery behavior, not only a successful click. Keep the environment and runtime boundaries explicit. A full-stack candidate should connect the UI’s state transitions with the API’s error and conflict contracts.','Action -> labeled form -> HTTP request -> validation\n-> trusted actor -> transaction -> response -> UI state\nThen repeat with an invalid value or another owner’s resource.','A diagram, a successful build and a self-checked task list do not establish a healthy end-to-end feature.'),
      section('Use real experience rather than invented polish','For a behavioral answer, state the situation, your responsibility, the action you personally took, the observed result and what you would change. Be clear about team work versus your contribution. An honest small debugging story is stronger evidence than invented impact numbers. Prepare examples of uncertainty, mistakes, disagreement, feedback, tradeoffs and learning.','Observed: a regression test failed before the repair and passed after.\nUnsupported: the repair improved retention by an invented percentage.','Do not turn a course exercise into a production-impact claim or invent users, revenue or hiring outcomes.'),
      section('Use a rehearsal to select the next practice task','A mock is a structured attempt, not a prediction of a hiring decision. Record which parts were independently checked, which were assisted and which explanations you reviewed yourself. Save the first attempt. After feedback, choose one concrete weakness, practice it and retry later. Ask a peer or interviewer for external feedback when possible, and confirm the actual format with the recruiter.','Debrief: contract unclear, boundary missed, explanation rushed.\nNext task: one lower-bound variation with equality and empty input.\nRetry: a fresh attempt on a later day.','Time spent and recognition XP are useful activity records, but they cannot prove independent interview performance.')],
    practice:[python('budget-pair','Rehearse a coding explanation'),sql('avoid-fanout','Rehearse a relational explanation')],links:[{href:'#studio',label:'Use the explanation studio'},{href:'#developer-path',label:'Continue the original project milestones'}],
    reflect:'Draft two honest experience stories and a five-minute walkthrough. Name one decision, rejected alternative, failing case, observed result and remaining limitation.',checks:[['walkthrough','I can trace a working feature and a rejected request.'],['experience','My experience stories distinguish my actions from team work.'],['debrief','I can choose a specific next task from mock feedback.']],followUp:'The interviewer adds concurrent editing or unreliable connectivity. Explain how both the frontend and backend behavior must change.'},
  ...JAVA_INTERVIEW_UNITS
];

export const MOCK_INTERVIEWS=[
  {id:'coding-rehearsal',title:'Coding and reasoning rehearsal',tracks:both,minutes:35,
    description:'Clarify, solve, test and explain two small original tasks without a worked answer. This is practice, not a standardized interview.',
    tasks:[python('stable-unique','Keep first-seen labels'),python('first-at-least','Find the first qualifying position')],
    phases:[['Clarify inputs and output',4],['Describe a baseline and invariant',6],['Implement and check',15],['Test boundary counterexamples',5],['Explain cost and a follow-up',5]],
    prompts:['Which ambiguity did you clarify before coding?','Which counterexample changed your first attempt?','Explain time/space and adapt one requirement without copying.'],
    checks:[['clarify','I restated the contract before coding.'],['reason','I explained an invariant and complexity.'],['adapt','I attempted a changed requirement before reading an answer.']]},
  {id:'backend-rehearsal',title:'Backend and data rehearsal',tracks:['backend','fullstack'],minutes:50,
    description:'Combine owner-scoped data access, a relational query and a written failure discussion. Code results and design reflection remain separate evidence.',
    tasks:[python('owner-scoped-read','Deny cross-owner access'),sql('avoid-fanout','Combine independent child measures')],
    phases:[['Clarify the API and result grain',5],['Implement and test ownership',15],['Write and test the query',15],['Explain retry or failure behavior',10],['Debrief',5]],
    prompts:['Where does the trusted actor come from? Show a denied request.','Why does the raw join multiply rows?','A write commits but its response is lost. Explain a safe replay policy.'],
    checks:[['owner','I explained authorization independently of validation.'],['data','I predicted missing and duplicate rows.'],['failure','I stated a durable retry boundary and a stopping rule.']]},
  {id:'fullstack-rehearsal',title:'Frontend and full-stack rehearsal',tracks:['fullstack'],minutes:55,
    description:'Use your own small web project for the UI portion, then check a SQL task here. Browser/React work is self-reported until you attach and review real project evidence.',
    tasks:[sql('paid-summary','Preserve customers without paid orders')],
    phases:[['State the form and API contract',5],['Implement a labeled responsive form in your project',20],['Test a request race and an error state',15],['Check SQL and explain the full request path',10],['Debrief',5]],
    prompts:['Show keyboard operation, validation feedback and a narrow-screen view.','Make the older request finish last. What prevents it replacing the latest result?','Trace a write through trusted ownership, persistence, conflict handling and UI recovery.'],
    checks:[['ui','I ran real browser/component checks in my own project.'],['states','I observed empty, loading, success, error and stale-response behavior.'],['boundary','I explained client feedback versus server validation and authorization.']]},
  JAVA_MOCK_INTERVIEW
];

export const UNIT_BY_ID=new Map(INTERVIEW_UNITS.map(unit=>[unit.id,unit]));
export const MOCK_BY_ID=new Map(MOCK_INTERVIEWS.map(mock=>[mock.id,mock]));
export const courseUnitsFor=target=>INTERVIEW_UNITS.filter(unit=>target==='both'||unit.tracks.includes(target));
